-- RA_RATIO[id]: percentage added to a skill's base 100% ratio, from SkillImpl::calculateSkillRatio
-- in src/map/skills/homunculus/*.cpp. lv = skill level, blv = the caster's base level, st = its
-- status (str, agi, vit, int, dex, luk). idiv truncates like C integer division.
local function idiv(a, b)
	local q = a / b
	if q >= 0 then return math.floor(q) end
	return -math.floor(-q)
end
RA_RATIO = {
